 "statements": [
  {
   "id": "3.2.2a",
   "type": "RULE",
   "force": "ADVISORY",
   "force_from": "text (\"should keep\")",
   "text": "a driver SHOULD keep to the right AND use the left lanes for passing WHILE driving on a freeway",
   "sources": [
    {
     "id": "m32",
     "quote": "Traffic should keep to the right, using the left lanes for passing."
    }
   ],
   "flags": [],
   "links": [],
   "note": null
  },
  {
   "id": "3.2.2b",
   "type": "RULE",
   "force": "ADVISORY",
   "force_from": "imperative (\"Use\")",
   "text": "a driver SHOULD use the far left lane of a multi-lane freeway to pass traffic moving slower than the speed limit AND SHOULD NOT stay in the far left lane WHILE driving on a multi-lane freeway",
   "sources": [
    {
     "id": "m33",
     "quote": "Use the far left lane of a multi-lane freeway to pass traffic moving slower than the speed limit, but don't stay there."
    }
   ],
   "flags": [],
   "links": [],
   "note": null
  },
  {
   "id": "3.2.2c",
   "type": "RULE",
   "force": "ADVISORY",
   "force_from": "imperative (\"Drive\")",
   "text": "a driver SHOULD drive in the right-hand lane WHEN possible WHILE driving on a freeway",
   "sources": [
    {
     "id": "m33",
     "quote": "Drive in the right-hand lane when possible."
    }
   ],
   "flags": [
    {
     "code": "J",
     "span": "possible",
     "note": "No definition of what makes driving in the right-hand lane possible or impossible."
    }
   ],
   "links": [],
   "note": null
  },
  {
   "id": "3.2.2d",
   "type": "RULE",
   "force": "LEGAL",
   "force_from": "text (\"must use\")",
   "text": "a truck driver MUST use the lane to the right of the far left lane for passing WHEN the freeway has three or more lanes in each direction AND the driver is in a large truck",
   "sources": [
    {
     "id": "m91",
     "quote": "On many freeways with three or more lanes in each direction, large trucks cannot travel in the far left lane and must use the lane to the right for passing."
    }
   ],
   "flags": [
    {
     "code": "S",
     "span": "many",
     "note": "The rule is stated to apply to 'many' freeways, not all, but no criteria are given for which ones."
    }
   ],
   "links": [],
   "note": "The prohibition on traveling in the far left lane is combined with the duty to use the lane to the right, as they describe the same lane usage requirement."
  },
  {
   "id": "3.2.2e",
   "type": "RULE",
   "force": "ADVISORY",
   "force_from": "imperative (\"Get into the habit\")",
   "text": "a driver SHOULD drive in the right lane WHILE driving on a freeway BECAUSE this leaves the other lanes clear for passing",
   "sources": [
    {
     "id": "m34",
     "quote": "Get into the habit of driving in the right lane, leaving the other lanes clear for passing."
    }
   ],
   "flags": [],
   "links": [],
   "note": null
  }
 ]
